-- Read-only local snapshot coverage; company.market defines the universe.
WITH latest AS (SELECT DISTINCT ON ("companyId") * FROM disclosure_report WHERE section='largestShareholders' AND "reportCode"='annual' AND "supersededById" IS NULL ORDER BY "companyId","bsnsYear" DESC,"rceptNo" DESC), coverage AS (SELECT c.id,c.name,c."corpCode",c.market,r."bsnsYear",r."settlementDate",EXISTS(SELECT 1 FROM shareholder_entry s WHERE s."reportId"=r.id AND NOT s."isTotal" AND s."sharesBegin" IS NOT NULL AND s."sharesEnd" IS NOT NULL AND s."sharesBegin"::numeric>=0 AND s."sharesEnd"::numeric>=0) usable FROM company c LEFT JOIN latest r ON r."companyId"=c.id WHERE c.market IN ('kospi','kosdaq','konex')) SELECT market,count(*) total,count("bsnsYear") reports,count(*) FILTER(WHERE usable) comparable,count(*) FILTER(WHERE usable AND "settlementDate" IS NOT NULL) dated FROM coverage GROUP BY market ORDER BY market;
